#[test]
fn sqlite_snapshot_iso16757_complete_semantic_cells_match_independent_physical_extent() {
 use std::{io::Write,process::{Command,Stdio}};
 let corpus:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/📏️cells/🔣️.json")).unwrap();
 let script=r#"import{Database}from'bun:sqlite';const c=JSON.parse(process.argv[1]);const d=Database.deserialize(await Bun.stdin.bytes(),{safeIntegers:true});if(d.query('PRAGMA integrity_check').get().integrity_check!=='ok'||d.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');const tables=d.query("SELECT name FROM sqlite_schema WHERE type='table' ORDER BY name").all();const census=[];for(const t of tables){const cols=d.query('PRAGMA table_info('+t.name+')').all().map(c=>'"'+c.name+'"');const extent=cols.map(c=>'CASE typeof('+c+') WHEN \'null\' THEN 0 WHEN \'integer\' THEN 8 WHEN \'real\' THEN 8 ELSE length(CAST('+c+' AS BLOB)) END').join('+');const r=d.query('SELECT count(*) AS rows,coalesce(sum('+extent+'),0) AS bytes FROM '+t.name).get();census.push({table:t.name,rows:Number(r.rows),semanticBytes:Number(r.bytes)});}if(JSON.stringify(census)!==JSON.stringify(c.perTable))throw Error('completeIndependentCensus');if(census.reduce((n,r)=>n+r.rows,0)!==c.rows||census.reduce((n,r)=>n+r.semanticBytes,0)!==c.semanticBytes)throw Error('completeIndependentTotals');await Bun.write(Bun.stdout,'[DEBUG] Independent ISO16757 semantic extent '+c.word+' '+c.rows+' '+c.semanticBytes);d.close();"#;
 for case in corpus["cases"].as_array().unwrap() {
  let word=case["word"].as_str().unwrap();let source=every_word(u64::from_str_radix(word,16).unwrap());let database=project(&source);
  assert_eq!(database.tables.len(),corpus["tableCount"].as_u64().unwrap()as usize);
  let bytes=store::sqlite_snapshot::export_sqlite_database(&database,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();
  let mut child=Command::new("bun").args(["--eval",script,&case.to_string()]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();
  child.stdin.take().unwrap().write_all(&bytes).unwrap();let result=child.wait_with_output().unwrap();assert!(result.status.success(),"{}",String::from_utf8_lossy(&result.stderr));println!("{}",String::from_utf8_lossy(&result.stdout));source.retire_sqlite_snapshot();
 }
}
