fn sqlite_snapshot_iso16757_complete_semantic_cells_apply_before_both_native_directions() {
 use store::sqlite_snapshot::SnapshotEncoding;
 let corpus:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/📏️cells/🔣️.json")).unwrap();
 for case in corpus["cases"].as_array().unwrap() {
  let word=case["word"].as_str().unwrap();let source=every_word(u64::from_str_radix(word,16).unwrap());let expected=project(&source);let bytes=case["semanticBytes"].as_u64().unwrap()as usize;let rows=case["rows"].as_u64().unwrap()as usize;
  for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text] {
   let payload=match encoding{SnapshotEncoding::Binary=>store::io_schema::IoPayload::Binary(<Iso16757Snapshot as store::ArtifactPack>::encode_pack(&source)),SnapshotEncoding::Text=>store::io_schema::IoPayload::Text(<Iso16757Snapshot as store::ArtifactDsl>::print_dsl(&source))};
   for maximum in [0,16,bytes-1,bytes] {
    let limits=SqliteDatabaseLimits{max_value_bytes:maximum,..SqliteDatabaseLimits::default()};
    let output=source.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,limits));
    assert_eq!(output.is_ok(),maximum==bytes,"{word} {encoding:?} actual native output semantic extent {maximum}");
    match output{Ok(actual)=>assert_eq!(actual,payload),Err(error)=>assert_eq!(error.kind,semio_framework_value::ValueRefusalKind::OwnershipLimit)}
    let restored=Iso16757Snapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,limits));
    assert_eq!(restored.is_ok(),maximum==bytes,"{word} {encoding:?} before typed native reconstruction semantic extent {maximum}");
    match restored{Ok(value)=>{assert_database(&project(&value),&expected,word);value.retire_sqlite_snapshot();},Err(error)=>assert_eq!(error.kind,semio_framework_value::ValueRefusalKind::OwnershipLimit)}
   }
   for maximum in [rows-1,rows] {
    let limits=SqliteDatabaseLimits{max_rows:maximum,..SqliteDatabaseLimits::default()};
    let output=source.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,limits));assert_eq!(output.is_ok(),maximum==rows,"{word} {encoding:?} actual row output {maximum}");
    let restored=Iso16757Snapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,limits));assert_eq!(restored.is_ok(),maximum==rows,"{word} {encoding:?} before typed row reconstruction {maximum}");
    if let Ok(value)=restored{assert_database(&project(&value),&expected,word);value.retire_sqlite_snapshot();}
   }
  }
  source.retire_sqlite_snapshot();
 }
}

