import Ajv from "ajv/dist/2020";
import admissionSchema from "../../🛬️native/🧬️schema/🔣️.json";
test("ISO16757 controlled wide catalogue corpus has independent cardinality and null-state semantics",()=>{
 expect(new Ajv({strict:true}).validate(admissionSchema,fixture.controlledAdmission)).toBe(true);
 const f=fixture.controlledAdmission,d=new Database(":memory:");
 const values=JSON.stringify(Array.from({length:f.wideListItems},()=>({kind:"null",state:"Unknown"})));
 const row=d.query("SELECT json_array_length(?) AS count,(SELECT count(*) FROM json_each(?) WHERE json_extract(value,'$.kind')='null' AND json_extract(value,'$.state')='Unknown') AS nulls").get(values,values) as {count:number;nulls:number};
 expect(row.count).toBe(f.wideListItems);expect(row.nulls).toBe(row.count);expect(f.cancelAfter).toBeLessThan(row.count);expect(f.maximumFrontierBytes).toBeLessThan(f.maximumOwnedBytes);d.close();
});

import semanticCells from "../../🧫️fixtures/🪶️sqlite/📏️cells/🔣️.json";
import semanticCellsSchema from "../../🧫️fixtures/🪶️sqlite/📏️cells/🧬️schema/🔣️.json";
test("ISO16757 complete semantic cell corpus has closed independent authority",()=>{
 const validate=new Ajv({strict:true}).compile(semanticCellsSchema);expect(validate(semanticCells)).toBe(true);
 expect(validate({...semanticCells,tableCount:54})).toBe(false);
 expect(validate({...semanticCells,cases:semanticCells.cases.map((c,n)=>n?c:{...c,semanticBytes:c.semanticBytes-1})})).toBe(false);
});
for(const c of semanticCells.cases)test("ISO16757 complete native-parity semantic cells "+c.word,async()=>{
 const bits=BigInt("0x"+c.word),s=snapshot(bits),pending:Array<Iso16757SqliteExtension>=Array.from(s.catalogue.extensions.fields.values());
 while(pending.length){const value=pending.pop()!;if(value.kind==="Float")value.value={bits};else if(value.kind==="Array")pending.push(...value.items);else if(value.kind==="Object")pending.push(...value.members.map(m=>m.value));}
 const d=await project(s,{maxValueBytes:c.semanticBytes,maxRows:c.rows});expect(d.tables.length).toBe(semanticCells.tableCount);
 const engine=Database.deserialize(await exportSqliteDatabase(d),{safeIntegers:true});
 expect(engine.query("PRAGMA integrity_check").get()).toEqual({integrity_check:"ok"});expect(engine.query("PRAGMA foreign_key_check").all()).toEqual([]);
 const census=c.perTable.map(t=>{const columns=(engine.query("PRAGMA table_info("+t.table+")").all()as{name:string}[]).map(v=>'"'+v.name+'"');const extent=columns.map(n=>"CASE typeof("+n+") WHEN 'null' THEN 0 WHEN 'integer' THEN 8 WHEN 'real' THEN 8 ELSE length(CAST("+n+" AS BLOB)) END").join("+");const r=engine.query("SELECT count(*) AS rows,coalesce(sum("+extent+"),0) AS bytes FROM "+t.table).get()as{rows:bigint;bytes:bigint};return{table:t.table,rows:Number(r.rows),semanticBytes:Number(r.bytes)};});
 expect(census).toEqual(c.perTable);expect(census.reduce((n,t)=>n+t.rows,0)).toBe(c.rows);expect(census.reduce((n,t)=>n+t.semanticBytes,0)).toBe(c.semanticBytes);engine.close();
 await expect(project(s,{maxValueBytes:c.semanticBytes-1})).rejects.toThrow();await expect(restore(d,{maxValueBytes:c.semanticBytes-1})).rejects.toThrow();await expect(project(s,{maxRows:c.rows-1})).rejects.toThrow();expect(await restore(d,{maxValueBytes:c.semanticBytes,maxRows:c.rows})).toEqual(s);
});
